const targets = [
  'Gene LC Inside Sales',
  'Ezzo LC Inside Sales',
].map(name => name.trim().toLowerCase());


let owners = [];

for (const item of $input.all()) {
  const results = item.json?.results || [];
  owners = owners.concat(results);
}

const matches = owners.filter(owner => {
  const fullName = `${owner.firstName || ''} ${owner.lastName || ''}`
    .trim()
    .toLowerCase();

  const email = (owner.email || '').trim().toLowerCase();

  return targets.includes(fullName) || targets.includes(email);
});

if (matches.length === 0) {
  const availableOwners = owners
    .map(owner =>
      `${owner.firstName || ''} ${owner.lastName || ''}`.trim()
    )
    .filter(Boolean)
    .join(', ');

  throw new Error(
    `No matching HubSpot owners found. Looking for: ${targets.join(', ')}. ` +
    `Available owners: ${availableOwners}`
  );
}

const missingOwners = targets.filter(target => {
  return !matches.some(owner => {
    const fullName = `${owner.firstName || ''} ${owner.lastName || ''}`
      .trim()
      .toLowerCase();

    const email = (owner.email || '').trim().toLowerCase();

    return fullName === target || email === target;
  });
});

if (missingOwners.length > 0) {
  const availableOwners = owners
    .map(owner =>
      `${owner.firstName || ''} ${owner.lastName || ''}`.trim()
    )
    .filter(Boolean)
    .join(', ');

  throw new Error(
    `These HubSpot owners were not found: ${missingOwners.join(', ')}. ` +
    `Available owners: ${availableOwners}`
  );
}

return matches.map(owner => ({
  json: {
    ownerId: String(owner.id),
    ownerName: `${owner.firstName || ''} ${owner.lastName || ''}`.trim(),
    ownerEmail: owner.email || ''
  }
}));

// const INDUSTRY_CAPS = {
//   'sporting goods or outdoor': 100,
//   'auto parts': 100,
//   'home goods': 100,
//   'industrial or manufacturing': 100,
//   'food and beverage': 30,
//   'other': 30,
//   'electronics': 75,
//   'apparel': 30,
//   'cosmetics': 20,
//   'medical': 20,
//   '3pl': 0,
//   'mixed': 20,
//   'na': 0
// };
const INDUSTRY_CAPS = $('Industry Cap').first().json.results;

const INDUSTRY_PROPERTY_NAME = 'industry_type_verified'; // <-- confirm exact internal property name

function normalizeIndustry(raw) {
  const v = (raw || '').toString().trim().toLowerCase();
  if (INDUSTRY_CAPS.hasOwnProperty(v)) return v;
  return 'other'; // unrecognized values bucket into "other"
}

const ownerTotalCounts = {};
const ownerIndustryCounts = {};

for (const item of $("Find Owner ID").all()) {
  ownerTotalCounts[item.json.ownerId] = 0;
  ownerIndustryCounts[item.json.ownerId] = {};
}

for (const item of $input.all()) {
  const records = item.json?.results || [item.json];
  for (const record of records) {
    const ownerId = record.properties?.hubspot_owner_id;
    // skip records with no owner or an owner not in our known list —
    // this node only counts EXISTING assignments per real owner
    if (!ownerId || !ownerTotalCounts.hasOwnProperty(ownerId)) continue;

    const industry = normalizeIndustry(record.properties?.[INDUSTRY_PROPERTY_NAME]);

    ownerTotalCounts[ownerId] = (ownerTotalCounts[ownerId] || 0) + 1;
    if (!ownerIndustryCounts[ownerId]) ownerIndustryCounts[ownerId] = {};
    ownerIndustryCounts[ownerId][industry] = (ownerIndustryCounts[ownerId][industry] || 0) + 1;
  }
}
let grandTotalLeads = 0;
const targetTotal = Number($("Total Leads to be Assigned to Each Owner").all()[0]?.json?.totalLeadsToBeAssigned) || 0;

const ownersInfo = Object.entries(ownerTotalCounts).map(([ownerId, count]) => {
  const ownerTotal = Math.max(0, targetTotal - count);
  grandTotalLeads += ownerTotal;

  const industryCapsRemaining = {};
  for (const [industry, cap] of Object.entries(INDUSTRY_CAPS)) {
    const alreadyAssigned = ownerIndustryCounts[ownerId]?.[industry] || 0;
    industryCapsRemaining[industry] = Math.max(0, cap - alreadyAssigned);
  }

  return { hubspot_owner_id: ownerId, totalLeads: ownerTotal, industryCapsRemaining };
});

return [{ json: { totalLeads: Math.max(0, grandTotalLeads), owners_info: ownersInfo } }];

const INDUSTRY_CAPS = $('Industry Cap').first().json.results;
const INDUSTRY_PROPERTY_NAME = 'industry_type_verified';

function normalizeIndustry(raw) {
  const v = (raw || '').toString().trim().toLowerCase();
  if (Object.prototype.hasOwnProperty.call(INDUSTRY_CAPS, v)) return v;
  return 'other';
}

const allocationItems = $('Get leads count to be assigned').all();
const assignments = allocationItems[0]?.json?.owners_info || [];

const ownerState = {};
let totalNeeded = 0;

for (const a of assignments) {
  ownerState[a.hubspot_owner_id] = {
    totalRemaining: a.totalLeads,
    industryRemaining: { ...a.industryCapsRemaining }
  };
  totalNeeded += a.totalLeads;
}

const ownerOrder = assignments.map(a => a.hubspot_owner_id);

// Split into Fresh vs Contacted pools
const companyItems = $input.all();
const freshPool = [];
const contactedPool = [];

for (const item of companyItems) {
  if (item.json.properties.notes_last_contacted == null) {
    freshPool.push(item);
  } else {
    contactedPool.push(item);
  }
}

// 50% Quota Target
let freshNeeded = Math.ceil(totalNeeded * 0.5);

const updates = [];
let ownerCursor = 0;

function assignCompany(company) {
  const industry = normalizeIndustry(company.json.properties?.[INDUSTRY_PROPERTY_NAME]);
  if ((INDUSTRY_CAPS[industry] || 0) === 0) return false;

  for (let attempt = 0; attempt < ownerOrder.length; attempt++) {
    const ownerId = ownerOrder[ownerCursor];
    ownerCursor = (ownerCursor + 1) % ownerOrder.length;
    const state = ownerState[ownerId];
    if (!state) continue;

    const industryLeft = state.industryRemaining[industry] ?? INDUSTRY_CAPS[industry];
    if (state.totalRemaining > 0 && industryLeft > 0) {
      updates.push({ id: String(company.json.id), properties: { hubspot_owner_id: ownerId } });
      state.totalRemaining -= 1;
      state.industryRemaining[industry] = industryLeft - 1;
      return true;
    }
  }
  return false;
}

// 1. Assign from Fresh pool up to 50% target
while (freshPool.length > 0 && freshNeeded > 0) {
  const company = freshPool.shift();
  if (assignCompany(company)) {
    freshNeeded--;
  }
}

// 2. Fill remaining quotas using Contacted pool first, then remaining Fresh pool
const remainingPool = [...contactedPool, ...freshPool];
for (const company of remainingPool) {
  assignCompany(company);
}

// Chunk into batches of 100 for HubSpot Batch Update endpoint
const BATCH_SIZE = 100;
const batches = [];
for (let i = 0; i < updates.length; i += BATCH_SIZE) {
  batches.push({ json: { inputs: updates.slice(i, i + BATCH_SIZE) } });
}

return batches;

const items = $input.all();
const passed = [];

for (const item of items) {
  const results = item.json?.results || [item.json];
  for (const company of results) {
    const props = company.properties || {};
    const annualRevenue = props.annualrevenue;
    const annualRevenueOk = annualRevenue === undefined || annualRevenue === null || annualRevenue === '' || Number(annualRevenue) < 50000000;
    if (!annualRevenueOk) continue;

    const apolloRevenue = props.apollo_annual_revenue_number_fix_use_this;
    const apolloRevenueOk = apolloRevenue === undefined || apolloRevenue === null || apolloRevenue === '' || Number(apolloRevenue) < 40000000;
    if (!apolloRevenueOk) continue;

    passed.push({ json: company });
  }
}

return passed;
